import { useEffect, useState, type ReactNode } from "react";
import { useSearchParams } from "react-router-dom";
import { agencyProposalTemplates, projectReportCatalog, type AgencyProposalTemplateId, type ProjectReportType } from "@webtummy/core/reporting";
import { api } from "../api.js";
import { useAuth } from "../auth.js";
import { Card } from "../components/ui.js";
import { getActiveProjectId, resolveActiveProjectId, setActiveProjectId } from "../active-project.js";
import { workspaceExperience } from "../workspace-experience.js";

type Project = { id: string; name: string; projectType: string; agencyClient?: { name: string } | null };
type ReportVersion = { id: string; version: number; contentJson: Record<string, unknown>; createdAt: string };
type StoredReport = { id: string; projectId: string; reportType: ProjectReportType; approvalStatus: string; documentStatus: string; currentVersion: number; qaStatus: string; qaJson: { checks?: { key: string; status: string; message: string }[] }; exportFormat: string; status: string; clientVisible: boolean; sentToClientAt?: string | null; periodStart?: string | null; periodEnd?: string | null; contentJson: Record<string, unknown>; createdAt: string; updatedAt: string; generatedBy?: string; customerCapacityUnits?: number; shareExpiresAt?: string | null; shareRevokedAt?: string | null; versions?: ReportVersion[]; acceptances?: { decision: string; accepterName: string | null; accepterEmail: string | null; actedAt: string }[] };
type ProposalDraft = { templateId: AgencyProposalTemplateId; title: string; executiveSummary: string; objectives: string[]; findings: string[]; opportunity: string; recommendedApproach: string[]; scope: string[]; deliverables: string[]; roadmap: string[]; timeline: string; investment: { currency: string; setupFee: string; monthlyFee: string; lineItems: { label: string; amount: string }[] }; addOns: string[]; expectedOutcomes: string[]; assumptions: string[]; exclusions: string[]; terms: string[]; nextSteps: string[] };
type AgencyBranding = { agencyName: string; agencyLogoFileId: string | null; agencyLogoDataUrl: string | null; preparedByName: string | null; contactEmail: string | null; contactPhone: string | null; websiteUrl: string | null; address: string | null; colorPreference: string; secondaryColor: string; footerDisclaimer: string | null; defaultTerms: string | null; senderSignature: string | null; minimizeSenukeBranding: boolean };

const emailFrequencyOptions = [
  { value: "immediate", label: "Immediate", detail: "Send each eligible email as soon as the event occurs." },
  { value: "daily", label: "Daily Summary", detail: "Combine eligible updates into one daily email." },
  { value: "weekly", label: "Weekly Summary", detail: "Combine eligible updates into one weekly email." },
  { value: "monthly", label: "Monthly Summary", detail: "Combine eligible updates into one monthly email." },
] as const;
type NotificationPreferences = { nonCriticalEmail: boolean; emailFrequency: (typeof emailFrequencyOptions)[number]["value"]; reportEmails: boolean; inAppNotifications: true };
type ReportFilter = "all" | "needs_review" | "qa_passed" | "approved" | "rejected" | "archived";
type BusinessSummary = { generatedAt: string; summary: { activeProjects: number; projects: number; averageSiteScore: number | null; completedTasks: number; blockedTasks: number; overdueTasks: number; reports: number; activityEvents: number }; projects: Array<{ id: string; name: string; status: string; siteScore: number | null; strategyStatus: string; completedTasks: number; totalTasks: number; blockedTasks: number; overdueTasks: number }> };

export default function ProjectReports() {
  const { user } = useAuth();
  const [params, setParams] = useSearchParams();
  const [projects, setProjects] = useState<Project[]>([]);
  const [projectId, setProjectId] = useState(params.get("projectId") || getActiveProjectId());
  const [reports, setReports] = useState<StoredReport[]>([]);
  const [reportFilter, setReportFilter] = useState<ReportFilter>("all");
  const [documentMode, setDocumentMode] = useState<"report" | "proposal">("report");
  const [reportType, setReportType] = useState<ProjectReportType>("monthly_growth");
  const [useAiNarrative, setUseAiNarrative] = useState(false);
  const [aiNarrativeEstimate, setAiNarrativeEstimate] = useState<{ capacityUnits: number; estimatedProviderCostUsd: number; requiresApproval: boolean } | null>(null);
  const [businessSummary, setBusinessSummary] = useState<BusinessSummary | null>(null);
  const [proposalTemplateId, setProposalTemplateId] = useState<AgencyProposalTemplateId>("seo_organic");
  const today = new Date().toISOString().slice(0, 10);
  const [periodStart, setPeriodStart] = useState(new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), 1)).toISOString().slice(0, 10));
  const [periodEnd, setPeriodEnd] = useState(today);
  const [selectedServices, setSelectedServices] = useState<string[]>([]);
  const [selectedFindings, setSelectedFindings] = useState<string[]>([]);
  const [notificationPreferences, setNotificationPreferences] = useState<NotificationPreferences>({ nonCriticalEmail: true, emailFrequency: "immediate", reportEmails: true, inAppNotifications: true });
  const [busy, setBusy] = useState("");
  const [linkCopyingId, setLinkCopyingId] = useState<string | null>(null);
  const [linkCopiedId, setLinkCopiedId] = useState<string | null>(null);
  const [message, setMessage] = useState("");
  const [editingProposal, setEditingProposal] = useState<StoredReport | null>(null);
  const [proposalDraft, setProposalDraft] = useState<ProposalDraft | null>(null);
  const [previewing, setPreviewing] = useState<StoredReport | null>(null);
  const [previewMode, setPreviewMode] = useState<"internal" | "client">("internal");
  const [historyReport, setHistoryReport] = useState<StoredReport | null>(null);
  const [editingReport, setEditingReport] = useState<StoredReport | null>(null);
  const [branding, setBranding] = useState<AgencyBranding | null>(null);
  const permissions = user?.workspace?.capabilities.permissions ?? {};
  const workspaceType = user?.workspace?.type;
  const experience = workspaceExperience(workspaceType);
  const isAgency = experience.kind === "agency";
  const availableTypes = projectReportCatalog.filter((item) => item.type !== "agency_proposal");

  const loadReports = async (id: string) => {
    if (!id) return setReports([]);
    const result = await api.get<{ reports: StoredReport[] }>(`/api/project-reports?projectId=${encodeURIComponent(id)}`);
    setReports(result.reports);
  };
  useEffect(() => {
    if (user?.workspace?.primaryRole !== "client_viewer") api.get<{ projects: Project[] }>("/api/projects-v2").then((result) => { setProjects(result.projects); const resolved = resolveActiveProjectId(result.projects, params.get("projectId"), projectId); if (resolved) setProjectId(resolved); }).catch(() => setProjects([]));
  }, []);
  useEffect(() => { api.get<{ preferences: typeof notificationPreferences }>("/api/notification-preferences").then((result) => setNotificationPreferences(result.preferences)).catch(() => undefined); }, []);
  useEffect(() => { api.get<{ aiNarrativeEstimate: typeof aiNarrativeEstimate }>("/api/project-reports/catalog").then((result) => setAiNarrativeEstimate(result.aiNarrativeEstimate)).catch(() => setAiNarrativeEstimate(null)); }, [workspaceType]);
  useEffect(() => { if (workspaceType === "agency") api.get<{ branding: AgencyBranding }>("/api/agency-report-branding").then((result) => setBranding(result.branding)).catch(() => setBranding(null)); }, [workspaceType]);
  useEffect(() => { if (workspaceType === "business") api.get<BusinessSummary>("/api/business-reports/summary").then(setBusinessSummary).catch(() => setBusinessSummary(null)); else setBusinessSummary(null); }, [workspaceType]);
  useEffect(() => { if (projectId) { setActiveProjectId(projectId); setParams((current) => { const next = new URLSearchParams(current); next.set("projectId", projectId); return next; }, { replace: true }); void loadReports(projectId).catch((error) => setMessage(error instanceof Error ? error.message : "Reports could not be loaded.")); } }, [projectId]);
  useEffect(() => { const reportId = params.get("reportId"); if (!reportId || previewing) return; const revision = params.get("revision"); void api.get<{ report: StoredReport; viewMode: "internal" | "client" }>(`/api/project-reports/${reportId}/preview${revision ? `?revision=${encodeURIComponent(revision)}` : ""}`).then((result) => { setPreviewMode(result.viewMode); setPreviewing(result.report); }).catch((error) => setMessage(error instanceof Error ? error.message : "Report could not be opened.")); }, [params, previewing]);
  useEffect(() => { const template = agencyProposalTemplates.find((item) => item.id === proposalTemplateId); if (isAgency && template && !selectedServices.length) setSelectedServices([...template.defaultServices]); }, [isAgency, proposalTemplateId]);
  useEffect(() => { if (!isAgency && documentMode === "proposal") setDocumentMode("report"); }, [documentMode, isAgency]);

  const generate = async () => {
    if (!(isAgency && documentMode === "proposal") && periodStart > periodEnd) { setMessage("Period start must be on or before period end."); return; }
    setBusy("generate"); setMessage("");
    const generatedType = isAgency && documentMode === "proposal" ? "agency_proposal" : reportType;
    try { const proposalMode = isAgency && documentMode === "proposal"; const payload = { projectId, reportType: generatedType, exportFormat: "pdf", templateId: proposalMode ? proposalTemplateId : undefined, selectedServices: proposalMode ? selectedServices : [], selectedFindings: proposalMode ? selectedFindings : [], periodStart: proposalMode ? undefined : new Date(`${periodStart}T00:00:00.000Z`).toISOString(), periodEnd: proposalMode ? undefined : new Date(`${periodEnd}T23:59:59.999Z`).toISOString(), useAiNarrative }; const result = await api.post<{ report: StoredReport; usage: { capacityUnits: number; charged: boolean } }>("/api/project-reports/generate", payload); await loadReports(projectId); if (!isAgency) await api.download(`/api/project-reports/${result.report.id}/download?revision=${result.report.currentVersion}`); setMessage(`Version ${result.report.currentVersion} created from current saved evidence and retained in Report History.${result.usage.charged ? ` ${result.usage.capacityUnits} AI Capacity units were used for the optional narrative.` : " No AI Capacity was used."}${isAgency ? " Review it before sharing." : " The PDF was downloaded."}`); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Report could not be generated."); }
    finally { setBusy(""); }
  };
  const decide = async (report: StoredReport, decision: "approved" | "rejected") => {
    setBusy(report.id); await api.patch(`/api/project-reports/${report.id}/approval`, { decision }); await loadReports(projectId); setBusy("");
  };
  const share = async (report: StoredReport) => {
    setBusy(report.id); await api.post(`/api/agency/reports/${report.id}/send-to-client`, {}); await loadReports(projectId); setBusy("");
  };
  const download = async (report: StoredReport) => {
    setBusy(report.id); setMessage("");
    try { await api.download(`/api/project-reports/${report.id}/download?revision=${report.currentVersion}`); }
    catch (error) { setMessage(error instanceof Error ? error.message : "PDF could not be downloaded."); }
    finally { setBusy(""); }
  };
  const saveNotificationPreferences = async () => {
    setBusy("preferences"); setMessage("");
    try { await api.patch("/api/notification-preferences", notificationPreferences); setMessage("Notification preferences saved. Critical failures remain enabled."); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Notification preferences could not be saved."); }
    finally { setBusy(""); }
  };
  const openProposalEditor = (report: StoredReport) => {
    const value = report.contentJson.proposal as ProposalDraft | undefined;
    if (!value) return setMessage("This proposal has no editable content.");
    setEditingProposal(report); setProposalDraft(normalizeProposal(value));
  };
  const saveProposal = async () => {
    if (!editingProposal || !proposalDraft) return;
    setBusy(editingProposal.id); setMessage("");
    try { await api.patch(`/api/agency-proposals/${editingProposal.id}`, proposalDraft); setEditingProposal(null); setProposalDraft(null); await loadReports(projectId); setMessage("Proposal saved as a new review draft. Approval is required before sending."); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Proposal could not be saved."); }
    finally { setBusy(""); }
  };
  const saveBranding = async () => {
    if (!branding) return; setBusy("branding"); setMessage("");
    try { await api.put("/api/agency-report-branding", branding); setMessage("White-label branding saved. New reports and proposals will use this branding snapshot."); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Branding could not be saved."); }
    finally { setBusy(""); }
  };
  const openHistory = async (report: StoredReport) => { setBusy(report.id); setMessage(""); try { const result = await api.get<{ report: StoredReport }>(`/api/project-reports/${report.id}/preview`); setHistoryReport(result.report); } catch (error) { setMessage(error instanceof Error ? error.message : "Version history could not be loaded."); } finally { setBusy(""); } };
  const openPreview = async (report: StoredReport, view: "internal" | "client" = "internal") => { setBusy(report.id); setMessage(""); try { const result = await api.get<{ report: StoredReport; viewMode: "internal" | "client" }>(`/api/project-reports/${report.id}/preview?view=${view}`); setPreviewMode(result.viewMode); setPreviewing(result.report); } catch (error) { setMessage(error instanceof Error ? error.message : "Report could not be opened."); } finally { setBusy(""); } };
  const copyReportLink = async (report: StoredReport) => { if (linkCopyingId) return; setLinkCopyingId(report.id); setLinkCopiedId(null); setMessage(""); try { let value: string; if (isAgency) { const url = new URL("/reports", window.location.origin); url.searchParams.set("projectId", projectId); url.searchParams.set("reportId", report.id); url.searchParams.set("revision", String(report.currentVersion)); value = url.toString(); } else { const result = await api.post<{ url: string; expiresAt: string }>(`/api/project-reports/${report.id}/share-link`, { expiresInDays: 14 }); value = result.url; } await copyText(value); setLinkCopiedId(report.id); setMessage(isAgency ? `Authenticated internal link to report version ${report.currentVersion} copied.` : "Client-safe report link copied. It expires in 14 days and can be revoked by creating a new link or using the API revoke action."); window.setTimeout(() => setLinkCopiedId((current) => current === report.id ? null : current), 2500); } catch (error) { setMessage(error instanceof Error ? error.message : "The secure report link could not be created."); } finally { setLinkCopyingId(null); } };
  const closePreview = () => { setPreviewing(null); if (params.has("reportId")) setParams((current) => { const next = new URLSearchParams(current); next.delete("reportId"); next.delete("revision"); return next; }, { replace: true }); };
  const archiveReport = async (report: StoredReport) => { if (!window.confirm(`Delete this ${report.reportType.replace(/_/g, " ")} draft from active reports? It will move to Archived, while all ${report.currentVersion} saved version${report.currentVersion === 1 ? "" : "s"} and its audit history remain recoverable.`)) return; setBusy(report.id); setMessage(""); try { await api.patch(`/api/project-reports/${report.id}/archive`, {}); setHistoryReport((current) => current?.id === report.id ? null : current); setPreviewing((current) => current?.id === report.id ? null : current); await loadReports(projectId); setReportFilter("all"); setMessage("Draft removed from active reports and moved to Archived. Its version history was retained."); } catch (error) { setMessage(error instanceof Error ? error.message : "Report could not be removed."); } finally { setBusy(""); } };
  const setProposalStatus = async (report: StoredReport, status: "accepted" | "declined" | "archived") => { const accepterName = status === "archived" ? null : window.prompt("Client/accepter name") || null; const accepterEmail = status === "archived" ? null : window.prompt("Client/accepter email") || null; setBusy(report.id); try { await api.patch(`/api/agency-proposals/${report.id}/status`, { status, accepterName, accepterEmail }); await loadReports(projectId); setMessage(`Proposal marked ${status}.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Proposal status could not be updated."); } finally { setBusy(""); } };
  const saveReport = async () => { if (!editingReport) return; setBusy(editingReport.id); try { await api.patch(`/api/project-reports/${editingReport.id}/content`, { title: String(editingReport.contentJson.title || "Project report"), openingNote: String(editingReport.contentJson.openingNote || "") || null, enabledOptionalSections: reportEnabledOptionalSections(editingReport) }); setEditingReport(null); await loadReports(projectId); setMessage("Report presentation saved. Its evidence and metrics remain locked."); } catch (error) { setMessage(error instanceof Error ? error.message : "Report could not be saved."); } finally { setBusy(""); } };

  const selectedDefinition = projectReportCatalog.find((item) => item.type === reportType);
  const filteredReports = reports.filter((report) => {
    if (reportFilter === "all") return report.documentStatus !== "archived";
    if (reportFilter === "archived") return report.documentStatus === "archived";
    if (reportFilter === "qa_passed") return report.documentStatus !== "archived" && report.qaStatus === "passed";
    return report.documentStatus !== "archived" && report.approvalStatus === reportFilter;
  });
  const reportFilterOptions: Array<{ key: ReportFilter; label: string; count: number; dot: string; active: string }> = [
    { key: "all", label: "All", count: reports.filter((report) => report.documentStatus !== "archived").length, dot: "bg-slate-400", active: "border-slate-800 bg-slate-900 text-white" },
    { key: "needs_review", label: "Needs review", count: reports.filter((report) => report.documentStatus !== "archived" && report.approvalStatus === "needs_review").length, dot: "bg-amber-500", active: "border-amber-500 bg-amber-50 text-amber-800" },
    { key: "qa_passed", label: "QA passed", count: reports.filter((report) => report.documentStatus !== "archived" && report.qaStatus === "passed").length, dot: "bg-emerald-500", active: "border-emerald-500 bg-emerald-50 text-emerald-800" },
    { key: "approved", label: "Approved", count: reports.filter((report) => report.documentStatus !== "archived" && report.approvalStatus === "approved").length, dot: "bg-blue-500", active: "border-blue-500 bg-blue-50 text-blue-800" },
    { key: "rejected", label: "Rejected", count: reports.filter((report) => report.documentStatus !== "archived" && report.approvalStatus === "rejected").length, dot: "bg-rose-500", active: "border-rose-500 bg-rose-50 text-rose-800" },
    { key: "archived", label: "Archived", count: reports.filter((report) => report.documentStatus === "archived").length, dot: "bg-slate-500", active: "border-slate-500 bg-slate-100 text-slate-800" },
  ];
  return <div className="space-y-6"><div><div className="text-xs font-bold uppercase tracking-wide text-brand-600">{experience.reportsEyebrow}</div><h1 className="mt-1 text-3xl font-bold text-slate-950">{experience.reportsTitle}</h1><p className="mt-2 text-sm text-slate-600">{experience.reportsDescription}</p></div>
    {!isAgency && reports.length > 0 && <EntrepreneurReportHistory reports={reports} busy={busy} onDownload={(report) => void download(report)} onHistory={(report) => void openHistory(report)} />}
    <WorkspaceProfilePanel workspaceName={user?.workspace?.name ?? "Workspace"} branding={workspaceType === "agency" && permissions.manage_settings ? branding : null} brandingBusy={busy === "branding"} notificationPreferences={notificationPreferences} notificationBusy={busy === "preferences"} onBrandingChange={setBranding} onSaveBranding={() => void saveBranding()} onNotificationChange={setNotificationPreferences} onSaveNotifications={() => void saveNotificationPreferences()} />
    {businessSummary && <Card className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-black uppercase tracking-wide text-brand-700">Business consolidated report</div><h2 className="mt-1 text-lg font-black text-slate-950">All projects and properties</h2><p className="mt-1 text-xs text-slate-500">Generate and download the current workspace-level PDF. It is not saved as a report version.</p></div>{permissions.export_reports && <button onClick={() => void api.download("/api/business-reports/download")} className="rounded-lg bg-slate-950 px-4 py-2 text-xs font-bold text-white">Download Business PDF</button>}</div><div className="mt-4 grid gap-3 sm:grid-cols-3 lg:grid-cols-5">{[{ label: "Active projects", value: businessSummary.summary.activeProjects }, { label: "Average site score", value: businessSummary.summary.averageSiteScore ?? "Pending" }, { label: "Completed", value: businessSummary.summary.completedTasks }, { label: "Blocked", value: businessSummary.summary.blockedTasks }, { label: "Overdue", value: businessSummary.summary.overdueTasks }].map((metric) => <div key={metric.label} className="rounded-xl border bg-slate-50 p-3"><div className="text-xl font-black text-slate-950">{metric.value}</div><div className="mt-1 text-[10px] font-bold uppercase tracking-wide text-slate-500">{metric.label}</div></div>)}</div><div className="mt-4 grid gap-2 md:grid-cols-2">{businessSummary.projects.map((project) => <div key={project.id} className="flex items-center justify-between gap-3 rounded-lg border px-3 py-2 text-xs"><div><div className="font-bold text-slate-900">{project.name}</div><div className="text-slate-500">Strategy {project.strategyStatus.replace(/_/g, " ")} · Site {project.siteScore ?? "pending"}</div></div><div className="text-right font-semibold text-slate-600">{project.completedTasks}/{project.totalTasks} complete<br />{project.overdueTasks} overdue</div></div>)}</div></Card>}
    {projects.length > 0 && <label className="block max-w-xl text-xs font-bold">Project<select value={projectId} onChange={(event) => setProjectId(event.target.value)} className="mt-1 h-11 w-full rounded-lg border bg-white px-3 text-sm font-normal">{projects.map((project) => <option key={project.id} value={project.id}>{project.agencyClient?.name ? `${project.agencyClient.name} · ` : ""}{project.name}</option>)}</select></label>}
    {message && <div className="rounded-lg border border-brand-200 bg-brand-50 px-4 py-3 text-sm text-brand-800">{message}</div>}
    {permissions.export_reports && projectId && <Card className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold">{isAgency ? "Create an Agency document" : "Generate a project report"}</h2><p className="mt-1 text-xs text-slate-500">{isAgency ? "Create a saved report or proposal from the current evidence, then review it before client delivery." : "Generate a versioned PDF from the project’s current saved evidence. The completed report is retained in Report History and downloaded immediately."}</p></div>{isAgency ? <div className="inline-flex rounded-lg border bg-slate-50 p-1"><button onClick={() => setDocumentMode("report")} className={`rounded-md px-3 py-2 text-xs font-bold ${documentMode === "report" ? "bg-white text-brand-700 shadow-sm" : "text-slate-500"}`}>Create report</button><button onClick={() => setDocumentMode("proposal")} className={`rounded-md px-3 py-2 text-xs font-bold ${documentMode === "proposal" ? "bg-white text-brand-700 shadow-sm" : "text-slate-500"}`}>Create proposal</button></div> : <span className="rounded-full bg-brand-50 px-3 py-1.5 text-xs font-bold text-brand-700">{experience.workspaceLabel}</span>}</div><div className="mt-4 grid gap-4 md:grid-cols-3">{isAgency && documentMode === "proposal" ? <label className="text-xs font-bold">Proposal template<select value={proposalTemplateId} onChange={(event) => { setProposalTemplateId(event.target.value as AgencyProposalTemplateId); setSelectedServices([]); }} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm font-normal">{agencyProposalTemplates.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label> : <><label className="text-xs font-bold">Report template<select value={reportType} onChange={(event) => setReportType(event.target.value as ProjectReportType)} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm font-normal">{availableTypes.map((item) => <option key={item.type} value={item.type}>{item.title}</option>)}</select></label><ReportInput label="Period start" type="date" value={periodStart} onChange={setPeriodStart} /><ReportInput label="Period end" type="date" value={periodEnd} onChange={setPeriodEnd} /></>}</div>{isAgency && documentMode === "proposal" && <div className="mt-4 grid gap-4 md:grid-cols-2"><ProposalList label="Services to include" value={selectedServices} onChange={setSelectedServices} /><ProposalList label="Evidence-backed findings to include" value={selectedFindings} onChange={setSelectedFindings} /></div>}<label className="mt-4 flex items-start gap-3 rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm"><input type="checkbox" checked={useAiNarrative} onChange={(event) => setUseAiNarrative(event.target.checked)} className="mt-0.5" /><span><strong>Use AI to write the executive narrative</strong><span className="mt-1 block text-xs text-slate-500">Optional · estimated {aiNarrativeEstimate?.capacityUnits ?? "configured"} AI Capacity units. Leave off for a deterministic evidence report at 0 AI Capacity.</span></span></label><div className="mt-4 rounded-xl border bg-slate-50 p-3"><div className="text-xs font-bold">Included sections</div><div className="mt-2 flex flex-wrap gap-2">{(isAgency && documentMode === "proposal" ? projectReportCatalog.find((item) => item.type === "agency_proposal") : selectedDefinition)?.sections.map((section) => <span key={section} className="rounded-full border bg-white px-2.5 py-1 text-[11px] text-slate-600">{section}</span>)}</div></div><div className="mt-4 flex items-center justify-between gap-3"><span className="text-xs text-slate-500">Generating this report approves the displayed {useAiNarrative ? `${aiNarrativeEstimate?.capacityUnits ?? "configured"} AI Capacity-unit` : "0 AI Capacity"} estimate. The completed report will be saved to Report History.</span><button disabled={busy !== ""} onClick={() => void generate()} className="h-10 shrink-0 rounded-lg bg-brand-600 px-4 text-sm font-bold text-white">{isAgency ? `Create ${documentMode === "proposal" ? "proposal" : "report"} draft` : "Generate, save & download PDF"}</button></div></Card>}
    {busy === "generate" && <div role="status" aria-live="polite" className="flex items-center gap-3 rounded-xl border border-white/10 bg-slate-950 px-4 py-4 text-sm text-white shadow-xl"><span aria-hidden="true" className="h-5 w-5 shrink-0 animate-spin rounded-full border-2 border-white/15 border-t-emerald-400" /><div><div className="font-bold">{isAgency ? "Creating document draft…" : "Generating your PDF…"}</div><div className="mt-0.5 text-xs text-slate-300">Collecting saved evidence, building the report sections, and preparing the download.</div></div></div>}
    {isAgency && reports.length > 0 && <div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-200 bg-white p-2 shadow-sm"><span className="px-2 text-[10px] font-black uppercase tracking-[0.14em] text-slate-400">Filter</span>{reportFilterOptions.map((option) => <button key={option.key} type="button" aria-pressed={reportFilter === option.key} onClick={() => setReportFilter(option.key)} className={`inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-bold transition ${reportFilter === option.key ? option.active : "border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50"}`}><span className={`h-2 w-2 rounded-full ${option.dot}`} />{option.label}<span className={`rounded-full px-1.5 py-0.5 text-[10px] ${reportFilter === option.key ? "bg-white/70 text-current" : "bg-slate-100 text-slate-500"}`}>{option.count}</span></button>)}</div>}
    {isAgency && <div className="space-y-3">{filteredReports.map((report) => {
      const definition = projectReportCatalog.find((item) => item.type === report.reportType);
      const content = report.contentJson as { execution?: { completed?: { title: string }[]; published?: string[]; awaitingApproval?: string[]; blocked?: string[] } };
      const narrative = reportNarrative(report.contentJson);
      const recordedActivity = (content.execution?.completed?.length ?? 0) + (content.execution?.published?.length ?? 0) + (content.execution?.awaitingApproval?.length ?? 0) + (content.execution?.blocked?.length ?? 0);
      const isArchived = report.documentStatus === "archived";
      const canArchive = report.reportType !== "agency_proposal" && !report.clientVisible && !report.sentToClientAt && report.documentStatus === "draft" && ["needs_review", "rejected"].includes(report.approvalStatus);
      const actionClass = "rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700 shadow-sm transition hover:border-brand-300 hover:text-brand-700 disabled:cursor-not-allowed disabled:opacity-50";
      return <Card key={report.id} className="group relative overflow-hidden border-slate-200 p-0 transition hover:border-brand-200 hover:shadow-md">
        <div className="absolute inset-y-0 left-0 w-1 bg-gradient-to-b from-brand-500 to-violet-500" />
        <div className="flex flex-col gap-4 p-4 pl-5 lg:flex-row lg:items-center">
          <div className="flex min-w-0 flex-1 items-center gap-4">
            <div className="grid h-16 w-16 shrink-0 place-items-center rounded-2xl bg-gradient-to-br from-brand-600 to-violet-600 text-white shadow-lg shadow-brand-100">
              <div className="text-center"><div className="text-[9px] font-black uppercase tracking-[0.18em] text-white/75">Version</div><div className="text-2xl font-black leading-none">{report.currentVersion}</div></div>
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <h2 className="truncate text-base font-black text-slate-950">{definition?.title || report.reportType}</h2>
                <StatusPill good={report.qaStatus === "passed"}>QA {report.qaStatus}</StatusPill>
                <StatusPill good={report.approvalStatus === "approved"}>{report.clientVisible ? "Shared" : report.approvalStatus === "approved" ? (isAgency ? "Ready to send" : "Ready") : report.approvalStatus.replace(/_/g, " ")}</StatusPill>
              </div>
              <p className="mt-1 text-xs text-slate-500"><span className="font-bold capitalize text-slate-700">{report.documentStatus.replace(/_/g, " ")}</span>{report.periodStart && report.periodEnd && <><span className="mx-2 text-slate-300">•</span><span className="font-semibold text-slate-600">{formatReportPeriod(report)}</span></>}<span className="mx-2 text-slate-300">•</span>Updated {new Date(report.updatedAt || report.createdAt).toLocaleString()}</p>
              <div className="mt-3 flex flex-wrap gap-x-5 gap-y-2">
                <ListMetric label="Completed" value={content.execution?.completed?.length ?? 0} tone="emerald" />
                <ListMetric label="Published" value={content.execution?.published?.length ?? 0} tone="blue" />
                <ListMetric label="Awaiting approval" value={content.execution?.awaitingApproval?.length ?? 0} tone="amber" />
                <ListMetric label="Blocked" value={content.execution?.blocked?.length ?? 0} tone="rose" />
              </div>
              {narrative && <p className="mt-3 line-clamp-2 max-w-3xl text-xs leading-5 text-slate-600">{narrative}</p>}
              {report.reportType === "campaign_project" && recordedActivity === 0 && <div className="mt-3 max-w-3xl rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs leading-5 text-amber-900"><strong>Baseline report:</strong> no execution activity was recorded in this period because the project is still at Intake. Preview the report for its objective, current assessment, risks, and recommended next step.</div>}
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2 lg:max-w-[420px] lg:justify-end">
            <button onClick={() => void openPreview(report, "internal")} className="rounded-lg bg-slate-950 px-3 py-2 text-xs font-bold text-white shadow-sm transition hover:bg-brand-700">{isAgency ? "Internal preview" : "Preview report"}</button>
            {isAgency && <button onClick={() => void openPreview(report, "client")} className={actionClass}>Client-safe preview</button>}
            {report.reportType === "agency_proposal" && permissions.export_reports && !report.clientVisible && !isArchived && <button disabled={busy === report.id} onClick={() => openProposalEditor(report)} className={actionClass}>Edit proposal</button>}
            {report.reportType !== "agency_proposal" && permissions.export_reports && !report.clientVisible && !isArchived && <button disabled={busy === report.id} onClick={() => setEditingReport(structuredClone(report))} className={actionClass}>Edit report</button>}
            <button disabled={busy === report.id} onClick={() => void download(report)} className={actionClass}>Download PDF</button>
            <button disabled={busy === report.id} onClick={() => void openHistory(report)} className={actionClass}>History</button>
            <button disabled={linkCopyingId !== null || (!isAgency && (report.qaStatus !== "passed" || report.approvalStatus !== "approved"))} aria-busy={linkCopyingId === report.id} onClick={() => void copyReportLink(report)} className={`${actionClass} inline-flex items-center gap-2`}>{linkCopyingId === report.id && <span aria-hidden="true" className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-slate-300 border-t-brand-700" />}{linkCopyingId === report.id ? "Creating…" : linkCopiedId === report.id ? "Copied ✓" : isAgency ? "Copy internal link" : "Create secure share link"}</button>
            {canArchive && <button disabled={busy === report.id} onClick={() => void archiveReport(report)} className="rounded-lg border border-red-200 bg-white px-3 py-2 text-xs font-bold text-red-700 shadow-sm transition hover:border-red-400 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-50">Delete draft</button>}
            {!isArchived && permissions.approve && report.approvalStatus === "needs_review" && <><button disabled={busy === report.id || report.qaStatus !== "passed"} onClick={() => void decide(report, "approved")} className="rounded-lg bg-brand-600 px-3 py-2 text-xs font-bold text-white shadow-sm transition hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-50">Approve</button><button disabled={busy === report.id} onClick={() => void decide(report, "rejected")} className={actionClass}>Reject</button></>}
            {!isArchived && workspaceType === "agency" && permissions.export_reports && report.approvalStatus === "approved" && !report.clientVisible && <button disabled={busy === report.id || report.qaStatus !== "passed"} onClick={() => void share(report)} className="rounded-lg bg-brand-600 px-3 py-2 text-xs font-bold text-white disabled:opacity-50">Send to client</button>}
            {report.reportType === "agency_proposal" && report.documentStatus === "sent" && <><button disabled={busy === report.id} onClick={() => void setProposalStatus(report, "accepted")} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-bold text-white">Record acceptance</button><button disabled={busy === report.id} onClick={() => void setProposalStatus(report, "declined")} className={actionClass}>Record decline</button></>}
            {report.reportType === "agency_proposal" && !["accepted", "declined", "archived"].includes(report.documentStatus) && <button disabled={busy === report.id} onClick={() => void setProposalStatus(report, "archived")} className={actionClass}>Archive</button>}
          </div>
        </div>
        {report.qaJson?.checks?.some((check) => check.status === "failed") && <div className="border-t border-red-100 bg-red-50 px-5 py-3 text-xs text-red-800"><div className="mb-1 font-bold">Automatic validation needs attention</div>{report.qaJson.checks.filter((check) => check.status === "failed").map((check) => <div key={check.key}>{check.message}</div>)}</div>}
      </Card>;
    })}{projectId && !reports.length && <Card className="p-8 text-center text-sm text-slate-500">No Agency documents have been generated for this project.</Card>}{reports.length > 0 && !filteredReports.length && <Card className="p-8 text-center text-sm text-slate-500">No reports match this filter.</Card>}</div>}
    {editingProposal && proposalDraft && <ProposalEditor value={proposalDraft} busy={busy === editingProposal.id} onChange={setProposalDraft} onClose={() => { setEditingProposal(null); setProposalDraft(null); }} onSave={() => void saveProposal()} />}
    {editingReport && <ReportEditor report={editingReport} busy={busy === editingReport.id} onChange={setEditingReport} onClose={() => setEditingReport(null)} onSave={() => void saveReport()} />}
    {historyReport && <VersionHistory report={historyReport} onClose={() => setHistoryReport(null)} onPreview={(version) => { setHistoryReport(null); setPreviewing({ ...historyReport, currentVersion: version.version, contentJson: version.contentJson, updatedAt: version.createdAt }); }} />}
    {previewing && <DocumentPreview report={previewing} viewMode={previewMode} onClose={closePreview} />}
  </div>;
}

function sectionKey(value: string) { return value.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, ""); }
function record(value: unknown): Record<string, any> { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : {}; }
function formatReportPeriod(report: Pick<StoredReport, "periodStart" | "periodEnd">) { if (!report.periodStart || !report.periodEnd) return ""; const format = (value: string) => new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }); return `${format(report.periodStart)} – ${format(report.periodEnd)}`; }
async function copyText(value: string) { if (navigator.clipboard?.writeText) { try { await navigator.clipboard.writeText(value); return; } catch { /* Use the local fallback below. */ } } const field = document.createElement("textarea"); field.value = value; field.setAttribute("readonly", ""); field.style.position = "fixed"; field.style.opacity = "0"; document.body.appendChild(field); field.select(); const copied = document.execCommand("copy"); field.remove(); if (!copied) throw new Error("Clipboard access was blocked."); }
function reportNarrative(content: Record<string, unknown>) { return String(record(content.clientNarrative).executiveNarrative || ""); }
function reportEnabledOptionalSections(report: StoredReport) { const definition = projectReportCatalog.find((item) => item.type === report.reportType); const optional = new Set((definition?.optionalSections ?? []).map(sectionKey)); return Array.isArray(report.contentJson.sections) ? report.contentJson.sections.filter((item) => optional.has(String(record(item).key)) && record(item).enabled !== false).map((item) => String(record(item).key)) : []; }
function normalizeProposal(value: ProposalDraft): ProposalDraft { const legacy: Record<string, AgencyProposalTemplateId> = { growth_strategy: "seo_organic", local_growth: "local_seo", content_authority_ai: "content_authority", growth_campaign: "custom" }; return { ...value, templateId: legacy[String(value.templateId)] ?? value.templateId ?? "seo_organic", findings: value.findings ?? [], recommendedApproach: value.recommendedApproach ?? value.scope ?? [], roadmap: value.roadmap ?? [], addOns: value.addOns ?? [], expectedOutcomes: value.expectedOutcomes ?? [], exclusions: value.exclusions ?? [], terms: value.terms ?? [] }; }
function readAgencyLogo(file: File | undefined, onRead: (value: string | null) => void) { if (!file) return; if (![/^image\/png$/, /^image\/jpeg$/].some((pattern) => pattern.test(file.type)) || file.size > 550_000) return window.alert("Choose a PNG or JPEG logo smaller than 550 KB."); const reader = new FileReader(); reader.onload = () => onRead(typeof reader.result === "string" ? reader.result : null); reader.readAsDataURL(file); }

function ListMetric({ label, value, tone }: { label: string; value: number; tone: "emerald" | "blue" | "amber" | "rose" }) { const tones = { emerald: "bg-emerald-500", blue: "bg-blue-500", amber: "bg-amber-500", rose: "bg-rose-500" }; return <span className="inline-flex items-center gap-2 text-xs text-slate-500"><span className={`h-2 w-2 rounded-full ${tones[tone]}`} /><strong className="text-sm text-slate-900">{value}</strong>{label}</span>; }
function StatusPill({ good, children }: { good: boolean; children: ReactNode }) { return <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${good ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700"}`}>{children}</span>; }

function EntrepreneurReportHistory({ reports, busy, onDownload, onHistory }: { reports: StoredReport[]; busy: string; onDownload: (report: StoredReport) => void; onHistory: (report: StoredReport) => void }) {
  const activeReports = reports.filter((report) => report.documentStatus !== "archived");
  return <Card className="p-5"><div><div className="text-xs font-black uppercase tracking-wide text-brand-700">Report history</div><h2 className="mt-1 text-lg font-black text-slate-950">Saved report versions</h2><p className="mt-1 text-xs leading-5 text-slate-500">Each generated report keeps its evidence snapshot. Download the current PDF or inspect earlier versions.</p></div><div className="mt-4 space-y-3">{activeReports.map((report) => { const definition = projectReportCatalog.find((item) => item.type === report.reportType); return <div key={report.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 bg-slate-50 p-4"><div><div className="font-bold text-slate-900">{definition?.title || report.reportType}</div><div className="mt-1 text-xs text-slate-500">Version {report.currentVersion}{report.periodStart && report.periodEnd ? ` · ${formatReportPeriod(report)}` : ""} · Updated {new Date(report.updatedAt).toLocaleString()}</div></div><div className="flex gap-2"><button disabled={busy === report.id} onClick={() => onDownload(report)} className="rounded-lg bg-brand-600 px-3 py-2 text-xs font-bold text-white disabled:opacity-50">Download PDF</button><button disabled={busy === report.id} onClick={() => onHistory(report)} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700 disabled:opacity-50">History</button></div></div>; })}{!activeReports.length && <p className="rounded-xl border border-dashed p-5 text-sm text-slate-500">No active report versions are available.</p>}</div></Card>;
}

function WorkspaceProfilePanel({ workspaceName, branding, brandingBusy, notificationPreferences, notificationBusy, onBrandingChange, onSaveBranding, onNotificationChange, onSaveNotifications }: { workspaceName: string; branding: AgencyBranding | null; brandingBusy: boolean; notificationPreferences: NotificationPreferences; notificationBusy: boolean; onBrandingChange: (value: AgencyBranding) => void; onSaveBranding: () => void; onNotificationChange: (value: NotificationPreferences) => void; onSaveNotifications: () => void }) {
  const identity = branding?.agencyName || workspaceName;
  return <Card className="overflow-hidden border-brand-200"><details className="group"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 p-5 marker:content-none"><div><span className="rounded-full bg-brand-50 px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide text-brand-700">Workspace-wide</span><h2 className="mt-2 font-bold">Workspace profile &amp; notifications</h2><p className="mt-1 text-xs text-slate-500">{identity} · Shared settings for every project in this workspace.</p></div><span aria-hidden="true" className="grid h-8 w-8 shrink-0 place-items-center rounded-full border text-slate-500 transition-transform group-open:rotate-180">⌄</span></summary><div className="border-t p-5">{branding && <AgencyBrandingPanel workspaceName={workspaceName} branding={branding} busy={brandingBusy} onChange={onBrandingChange} onSave={onSaveBranding} embedded />}<section className={branding ? "mt-6 border-t pt-6" : ""}><div><h3 className="font-bold">Notification delivery</h3><p className="mt-1 text-xs leading-5 text-slate-500">Choose how you receive non-critical updates across every project. Critical security, integration, and publishing failures cannot be disabled.</p></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="flex items-center gap-3 rounded-xl border p-3 text-sm font-semibold"><input type="checkbox" checked={notificationPreferences.nonCriticalEmail} onChange={(event) => onNotificationChange({ ...notificationPreferences, nonCriticalEmail: event.target.checked })} /> Non-critical emails</label><label className="flex items-center gap-3 rounded-xl border p-3 text-sm font-semibold"><input type="checkbox" checked={notificationPreferences.reportEmails} onChange={(event) => onNotificationChange({ ...notificationPreferences, reportEmails: event.target.checked })} /> Report emails</label></div><fieldset className="mt-5"><legend className="text-xs font-bold text-slate-700">Email frequency <span className="font-normal text-slate-500">· Choose one</span></legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{emailFrequencyOptions.map((option) => <label key={option.value} className={`flex cursor-pointer items-start gap-3 rounded-xl border p-3 ${notificationPreferences.emailFrequency === option.value ? "border-brand-400 bg-brand-50" : "border-slate-200 bg-white"}`}><input type="radio" name="workspace-email-frequency" value={option.value} checked={notificationPreferences.emailFrequency === option.value} onChange={() => onNotificationChange({ ...notificationPreferences, emailFrequency: option.value })} className="mt-0.5" /><span><span className="block text-sm font-bold text-slate-800">{option.label}</span><span className="mt-0.5 block text-xs leading-5 text-slate-500">{option.detail}</span></span></label>)}</div></fieldset><div className="mt-5 flex justify-end"><button disabled={notificationBusy} onClick={onSaveNotifications} className="h-10 rounded-lg bg-brand-600 px-4 text-sm font-bold text-white disabled:opacity-50">{notificationBusy ? "Saving…" : "Save notification preferences"}</button></div></section></div></details></Card>;
}

function AgencyBrandingPanel({ workspaceName, branding, busy, onChange, onSave, embedded = false }: { workspaceName: string; branding: AgencyBranding; busy: boolean; onChange: (value: AgencyBranding) => void; onSave: () => void; embedded?: boolean }) {
  return <Card className={embedded ? "border-0 shadow-none" : "overflow-hidden border-brand-200"}><details className="group" open={embedded}><summary className={embedded ? "hidden" : "flex cursor-pointer list-none items-center justify-between gap-4 p-5 marker:content-none"}><div><div className="mb-2 flex flex-wrap items-center gap-2"><span className="rounded-full bg-brand-50 px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide text-brand-700">Workspace-wide</span><span className="text-xs font-semibold text-slate-500">{workspaceName}</span></div><h2 className="font-bold">Shared Agency Brand Profile</h2><p className="mt-1 text-xs text-slate-500">{branding.agencyName || "Configure agency branding"} · Applies to every project, proposal, and report in this workspace.</p></div><span aria-hidden="true" className="grid h-8 w-8 shrink-0 place-items-center rounded-full border text-slate-500 transition-transform group-open:rotate-180">⌄</span></summary><div className={embedded ? "p-0" : "border-t p-5"}><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-bold">Shared Agency Brand Profile</h3><p className="mt-1 text-xs text-slate-500">Update this shared profile only when your agency identity or document defaults change.</p></div><button disabled={busy} onClick={onSave} className="h-10 rounded-lg bg-brand-600 px-4 text-sm font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Save brand profile"}</button></div><div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><ReportInput label="Agency name" value={branding.agencyName} onChange={(value) => onChange({ ...branding, agencyName: value })} /><ReportInput label="Logo file/reference" value={branding.agencyLogoFileId ?? ""} onChange={(value) => onChange({ ...branding, agencyLogoFileId: value || null })} /><ReportInput label="Prepared by" value={branding.preparedByName ?? ""} onChange={(value) => onChange({ ...branding, preparedByName: value || null })} /><ReportInput label="Contact email" value={branding.contactEmail ?? ""} onChange={(value) => onChange({ ...branding, contactEmail: value || null })} /><ReportInput label="Contact phone" value={branding.contactPhone ?? ""} onChange={(value) => onChange({ ...branding, contactPhone: value || null })} /><ReportInput label="Website" value={branding.websiteUrl ?? ""} onChange={(value) => onChange({ ...branding, websiteUrl: value || null })} /><ReportInput label="Address" value={branding.address ?? ""} onChange={(value) => onChange({ ...branding, address: value || null })} /><label className="text-xs font-bold">Primary colour<input type="color" value={branding.colorPreference} onChange={(event) => onChange({ ...branding, colorPreference: event.target.value })} className="mt-1 h-10 w-full rounded-lg border bg-white px-2" /></label><label className="text-xs font-bold">Secondary colour<input type="color" value={branding.secondaryColor} onChange={(event) => onChange({ ...branding, secondaryColor: event.target.value })} className="mt-1 h-10 w-full rounded-lg border bg-white px-2" /></label><ReportInput label="Footer / disclaimer" value={branding.footerDisclaimer ?? ""} onChange={(value) => onChange({ ...branding, footerDisclaimer: value || null })} /><ReportInput label="Default terms" value={branding.defaultTerms ?? ""} onChange={(value) => onChange({ ...branding, defaultTerms: value || null })} /><ReportInput label="Sender / signature" value={branding.senderSignature ?? ""} onChange={(value) => onChange({ ...branding, senderSignature: value || null })} /></div><div className="mt-4 flex flex-wrap items-center gap-3 rounded-xl border bg-slate-50 p-3">{branding.agencyLogoDataUrl ? <img src={branding.agencyLogoDataUrl} alt="Agency logo preview" className="h-14 w-32 rounded-lg border bg-white object-contain p-2" /> : <div className="grid h-14 w-32 place-items-center rounded-lg border border-dashed bg-white text-[10px] font-bold uppercase text-slate-400">No PDF logo</div>}<label className="cursor-pointer rounded-lg border bg-white px-3 py-2 text-xs font-bold">Upload PNG/JPEG<input type="file" accept="image/png,image/jpeg" className="hidden" onChange={(event) => void readAgencyLogo(event.target.files?.[0], (agencyLogoDataUrl) => onChange({ ...branding, agencyLogoDataUrl }))} /></label>{branding.agencyLogoDataUrl && <button type="button" onClick={() => onChange({ ...branding, agencyLogoDataUrl: null })} className="rounded-lg border px-3 py-2 text-xs font-bold text-red-700">Remove logo</button>}<span className="text-xs text-slate-500">Maximum 550 KB. The image is stored in the shared Agency profile and embedded in PDFs.</span></div><label className="mt-4 flex items-center gap-2 text-sm"><input type="checkbox" checked={branding.minimizeSenukeBranding} onChange={(event) => onChange({ ...branding, minimizeSenukeBranding: event.target.checked })} /> Minimize SEnuke AI - AI Growth Operating System branding on client-facing PDFs</label></div></details></Card>;
}

function ReportInput({ label, value, onChange, type = "text" }: { label: string; value: string; onChange: (value: string) => void; type?: string }) { return <label className="text-xs font-bold">{label}<input type={type} value={value} onChange={(event) => onChange(event.target.value)} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm font-normal" /></label>; }
function lines(value: string) { return value.split("\n").map((item) => item.trim()).filter(Boolean); }
function ProposalList({ label, value, onChange }: { label: string; value: string[]; onChange: (value: string[]) => void }) { return <label className="text-xs font-bold">{label}<textarea rows={4} value={value.join("\n")} onChange={(event) => onChange(lines(event.target.value))} className="mt-1 w-full rounded-lg border bg-white px-3 py-2 text-sm font-normal" /><span className="mt-1 block font-normal text-slate-400">One item per line</span></label>; }

function ProposalEditor({ value, busy, onChange, onClose, onSave }: { value: ProposalDraft; busy: boolean; onChange: (value: ProposalDraft) => void; onClose: () => void; onSave: () => void }) {
  return <div className="fixed inset-0 z-[100] flex items-center justify-center p-4"><button type="button" className="absolute inset-0 bg-slate-950/50" aria-label="Close proposal editor" onClick={onClose} /><div className="relative max-h-[92vh] w-full max-w-5xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="sticky top-0 z-10 flex items-start justify-between border-b bg-white px-6 py-4"><div><h2 className="text-xl font-bold text-slate-950">Edit Agency proposal</h2><p className="mt-1 text-xs text-slate-500">Saving creates a new immutable version and returns it to review.</p></div><button onClick={onClose} className="rounded-lg border px-3 py-2 text-xs font-bold">Close</button></div><div className="space-y-6 p-6"><div className="grid gap-4 md:grid-cols-3"><label className="text-xs font-bold">Proposal type<select value={value.templateId} onChange={(event) => onChange({ ...value, templateId: event.target.value as AgencyProposalTemplateId })} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm font-normal">{agencyProposalTemplates.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><ReportInput label="Proposal title" value={value.title} onChange={(title) => onChange({ ...value, title })} /><ReportInput label="Timeline" value={value.timeline} onChange={(timeline) => onChange({ ...value, timeline })} /></div><label className="block text-xs font-bold">Executive summary<textarea rows={5} value={value.executiveSummary} onChange={(event) => onChange({ ...value, executiveSummary: event.target.value })} className="mt-1 w-full rounded-lg border px-3 py-2 text-sm font-normal" /></label><label className="block text-xs font-bold">Priority opportunity<textarea rows={3} value={value.opportunity} onChange={(event) => onChange({ ...value, opportunity: event.target.value })} className="mt-1 w-full rounded-lg border px-3 py-2 text-sm font-normal" /></label><div className="grid gap-4 md:grid-cols-2"><ProposalList label="Client objectives" value={value.objectives} onChange={(objectives) => onChange({ ...value, objectives })} /><ProposalList label="What we found" value={value.findings} onChange={(findings) => onChange({ ...value, findings })} /><ProposalList label="Recommended approach/services" value={value.recommendedApproach} onChange={(recommendedApproach) => onChange({ ...value, recommendedApproach })} /><ProposalList label="Scope of work" value={value.scope} onChange={(scope) => onChange({ ...value, scope })} /><ProposalList label="Deliverables" value={value.deliverables} onChange={(deliverables) => onChange({ ...value, deliverables })} /><ProposalList label="Initial roadmap" value={value.roadmap} onChange={(roadmap) => onChange({ ...value, roadmap })} /></div><div className="rounded-xl border bg-slate-50 p-4"><h3 className="font-bold">Agency-entered investment</h3><div className="mt-3 grid gap-4 md:grid-cols-3"><ReportInput label="Currency" value={value.investment.currency} onChange={(currency) => onChange({ ...value, investment: { ...value.investment, currency } })} /><ReportInput label="Setup investment" value={value.investment.setupFee} onChange={(setupFee) => onChange({ ...value, investment: { ...value.investment, setupFee } })} /><ReportInput label="Monthly investment" value={value.investment.monthlyFee} onChange={(monthlyFee) => onChange({ ...value, investment: { ...value.investment, monthlyFee } })} /></div><label className="mt-4 block text-xs font-bold">Line items<textarea rows={4} value={value.investment.lineItems.map((item) => `${item.label} | ${item.amount}`).join("\n")} onChange={(event) => onChange({ ...value, investment: { ...value.investment, lineItems: lines(event.target.value).map((item) => { const [label, ...amount] = item.split("|"); return { label: label.trim(), amount: amount.join("|").trim() || "TBD" }; }) } })} className="mt-1 w-full rounded-lg border bg-white px-3 py-2 text-sm font-normal" /><span className="mt-1 block font-normal text-slate-400">One item per line: Service | Amount. Replace all TBD values before approval.</span></label></div><div className="grid gap-4 md:grid-cols-2"><ProposalList label="Optional add-ons" value={value.addOns} onChange={(addOns) => onChange({ ...value, addOns })} /><ProposalList label="Expected outcomes" value={value.expectedOutcomes} onChange={(expectedOutcomes) => onChange({ ...value, expectedOutcomes })} /><ProposalList label="Assumptions" value={value.assumptions} onChange={(assumptions) => onChange({ ...value, assumptions })} /><ProposalList label="Exclusions" value={value.exclusions} onChange={(exclusions) => onChange({ ...value, exclusions })} /><ProposalList label="Terms" value={value.terms} onChange={(terms) => onChange({ ...value, terms })} /><ProposalList label="Next steps" value={value.nextSteps} onChange={(nextSteps) => onChange({ ...value, nextSteps })} /></div></div><div className="sticky bottom-0 flex justify-end gap-2 border-t bg-white px-6 py-4"><button onClick={onClose} className="rounded-lg border px-4 py-2 text-sm font-bold">Cancel</button><button disabled={busy} onClick={onSave} className="rounded-lg bg-brand-600 px-4 py-2 text-sm font-bold text-white">{busy ? "Saving…" : "Create new review version"}</button></div></div></div>;
}

function ReportEditor({ report, busy, onChange, onClose, onSave }: { report: StoredReport; busy: boolean; onChange: (value: StoredReport) => void; onClose: () => void; onSave: () => void }) {
  const sections = Array.isArray(report.contentJson.sections) ? report.contentJson.sections.map(record) : [];
  const definition = projectReportCatalog.find((item) => item.type === report.reportType);
  const optional = new Set((definition?.optionalSections ?? []).map(sectionKey));
  const optionalSections = sections.filter((section) => optional.has(String(section.key)));
  const updateContent = (next: Record<string, unknown>) => onChange({ ...report, contentJson: next });
  return <div className="fixed inset-0 z-[100] flex items-center justify-center p-4"><button type="button" className="absolute inset-0 bg-slate-950/50" aria-label="Close report editor" onClick={onClose} /><div className="relative max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="sticky top-0 z-10 flex justify-between border-b bg-white px-6 py-4"><div><h2 className="text-xl font-bold">Review report version {report.currentVersion}</h2><p className="mt-1 text-xs text-slate-500">Presentation settings apply to this draft. Evidence, metrics, limitations, serious problems, and the Next Best Action are locked.</p></div><button onClick={onClose} className="rounded-lg border px-3 py-2 text-xs font-bold">Close</button></div><div className="space-y-5 p-6"><ReportInput label="Report title" value={String(report.contentJson.title || definition?.title || "Client report")} onChange={(title) => updateContent({ ...report.contentJson, title })} /><label className="block text-xs font-bold">Opening note <span className="font-normal text-slate-400">· one line</span><input type="text" maxLength={600} value={String(report.contentJson.openingNote || "")} onChange={(event) => updateContent({ ...report.contentJson, openingNote: event.target.value })} className="mt-1 h-10 w-full rounded-lg border px-3 text-sm font-normal" /></label><div className="rounded-xl border border-blue-100 bg-blue-50 p-4 text-xs leading-5 text-blue-800"><strong>Locked report facts</strong><br />The generated explanation, performance metrics, source labels, important limitations, serious problems, and recommended Next Best Action cannot be rewritten here.</div><div><div className="text-xs font-bold">Optional sections</div><div className="mt-2 grid gap-2 sm:grid-cols-2">{optionalSections.map((section) => { const index = sections.findIndex((item) => item.key === section.key); return <label key={String(section.key)} className="flex items-center gap-2 rounded-lg border p-3 text-sm"><input type="checkbox" checked={section.enabled !== false} onChange={(event) => updateContent({ ...report.contentJson, sections: sections.map((item, itemIndex) => itemIndex === index ? { ...item, enabled: event.target.checked } : item) })} /> {String(section.title)}</label>; })}{!optionalSections.length && <p className="text-sm text-slate-500">This template has no optional sections.</p>}</div></div></div><div className="sticky bottom-0 flex justify-end gap-2 border-t bg-white px-6 py-4"><button onClick={onClose} className="rounded-lg border px-4 py-2 text-sm font-bold">Cancel</button><button disabled={busy} onClick={onSave} className="rounded-lg bg-brand-600 px-4 py-2 text-sm font-bold text-white">{busy ? "Saving…" : "Save review settings"}</button></div></div></div>;
}

function VersionHistory({ report, onClose, onPreview }: { report: StoredReport; onClose: () => void; onPreview: (version: ReportVersion) => void }) {
  const versions = report.versions ?? [];
  return <div className="fixed inset-0 z-[105] flex items-center justify-center p-4"><button type="button" className="absolute inset-0 bg-slate-950/60" aria-label="Close version history" onClick={onClose} /><section className="relative max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-slate-50 shadow-2xl"><header className="sticky top-0 z-10 flex items-start justify-between gap-4 border-b bg-white px-6 py-5"><div><div className="text-xs font-black uppercase tracking-[0.14em] text-brand-700">Version history</div><h2 className="mt-1 text-xl font-black text-slate-950">{String(report.contentJson.title || report.reportType)}</h2><p className="mt-1 text-xs text-slate-500">Every saved version keeps its original content and evidence snapshot.</p></div><button onClick={onClose} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700">Close</button></header><div className="space-y-3 p-5">{versions.map((version) => { const current = version.version === report.currentVersion; const versionContent = record(version.contentJson); const source = record(versionContent.sourceSnapshot); return <article key={version.id} className={`flex flex-col gap-4 rounded-xl border bg-white p-4 sm:flex-row sm:items-center ${current ? "border-brand-300 shadow-sm ring-1 ring-brand-100" : "border-slate-200"}`}><div className={`grid h-14 w-14 shrink-0 place-items-center rounded-xl ${current ? "bg-gradient-to-br from-brand-600 to-violet-600 text-white" : "bg-slate-100 text-slate-700"}`}><div className="text-center"><div className="text-[8px] font-black uppercase tracking-widest opacity-70">Version</div><div className="text-xl font-black leading-none">{version.version}</div></div></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-black text-slate-900">{current ? "Current draft" : `Previous version ${version.version}`}</h3>{current && <span className="rounded-full bg-brand-50 px-2 py-1 text-[10px] font-black uppercase text-brand-700">Latest</span>}</div><p className="mt-1 text-xs text-slate-500">Created {new Date(version.createdAt).toLocaleString()}</p>{source.capturedAt && <p className="mt-1 truncate text-[11px] text-slate-400">Evidence captured {new Date(String(source.capturedAt)).toLocaleString()}</p>}</div><button onClick={() => onPreview(version)} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700 transition hover:border-brand-300 hover:text-brand-700">Preview version</button></article>; })}{!versions.length && <div className="rounded-xl border border-dashed border-slate-300 bg-white p-8 text-center text-sm text-slate-500">No saved versions were found.</div>}</div></section></div>;
}

function DocumentPreview({ report, viewMode, onClose }: { report: StoredReport; viewMode: "internal" | "client"; onClose: () => void }) {
  const content = report.contentJson; const proposal = record(content.proposal); const narrative = record(content.clientNarrative); const project = record(content.project); const period = record(content.reportingPeriod);
  return <div className="fixed inset-0 z-[110] flex items-center justify-center p-4"><button type="button" className="absolute inset-0 bg-slate-950/60" aria-label="Close document preview" onClick={onClose} /><article className="relative max-h-[94vh] w-full max-w-4xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><header className="border-b bg-slate-950 px-8 py-8 text-white"><div className="text-xs font-bold uppercase tracking-widest text-brand-300">{report.reportType === "agency_proposal" ? "Client proposal preview" : viewMode === "client" ? "Client-safe report preview" : "Internal report preview"}</div><h2 className="mt-3 text-3xl font-bold">{String(proposal.title || content.title || report.reportType)}</h2><p className="mt-2 text-sm text-slate-300">{String(project.name || "")} · Version {report.currentVersion}{period.start ? ` · ${new Date(String(period.start)).toLocaleDateString(undefined, { timeZone: "UTC" })}–${new Date(String(period.end)).toLocaleDateString(undefined, { timeZone: "UTC" })}` : ""}</p></header><div className="space-y-6 p-8">{proposal.title ? <><PreviewSection title="Executive summary" value={proposal.executiveSummary} /><PreviewList title="What we found" value={proposal.findings} /><PreviewSection title="Priority opportunity" value={proposal.opportunity} /><PreviewList title="Scope" value={proposal.scope} /><PreviewList title="Deliverables" value={proposal.deliverables} /><PreviewList title="Expected outcomes" value={proposal.expectedOutcomes} /><PreviewList title="Terms and exclusions" value={[...(Array.isArray(proposal.terms) ? proposal.terms : []), ...(Array.isArray(proposal.exclusions) ? proposal.exclusions : [])]} /></> : <><PreviewSection title="Opening note" value={content.openingNote || content.agencyNotes} /><PreviewSection title="Executive explanation" value={narrative.executiveNarrative} /><PreviewSection title="What this means" value={narrative.interpretation} />{Array.isArray(content.clientSections) ? <PreviewClientSections content={content} /> : <><PreviewList title="Wins" value={narrative.wins} /><PreviewList title="Risks" value={narrative.risks} /><PreviewList title="Next priorities" value={content.recommendations} /></>}</>}<div className="rounded-lg bg-slate-50 p-4 text-xs text-slate-600">View: {viewMode === "client" ? "client-safe" : "internal"} · QA: {report.qaStatus} · Approval: {report.approvalStatus} · Status: {report.documentStatus}</div></div><div className="sticky bottom-0 flex justify-end border-t bg-white px-6 py-4"><button onClick={onClose} className="rounded-lg border px-4 py-2 text-sm font-bold">Close preview</button></div></article></div>;
}

function PreviewClientSections({ content }: { content: Record<string, unknown> }) {
  const enabled = new Map((Array.isArray(content.sections) ? content.sections : []).map((item) => [String(record(item).key), record(item).enabled !== false]));
  const sections = (Array.isArray(content.clientSections) ? content.clientSections : []).map(record).filter((section) => enabled.get(String(section.key)) !== false);
  return <div className="space-y-7">{sections.map((section) => { const metrics = Array.isArray(section.metrics) ? section.metrics.map(record) : []; const items = Array.isArray(section.items) ? section.items : []; return <section key={String(section.key)} className="border-t border-slate-100 pt-6 first:border-0 first:pt-0"><h3 className="text-lg font-bold text-slate-950">{String(section.title)}</h3>{section.summary && <p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-700">{String(section.summary)}</p>}{metrics.length > 0 && <div className="mt-3 grid gap-3 sm:grid-cols-3">{metrics.map((metric, index) => <div key={`${String(metric.label)}-${index}`} className="rounded-xl border bg-slate-50 p-3"><div className="text-lg font-black text-slate-950">{formatPreviewValue(metric.value)}</div><div className="mt-1 text-[11px] font-bold uppercase tracking-wide text-slate-500">{String(metric.label)}</div>{metric.note && <div className="mt-1 text-[11px] text-slate-400">{String(metric.note)}</div>}</div>)}</div>}{items.length > 0 ? <ul className="mt-3 list-disc space-y-1.5 pl-5 text-sm leading-6 text-slate-700">{items.map((item, index) => <li key={index}>{previewItem(item)}</li>)}</ul> : section.emptyMessage && <p className="mt-3 rounded-lg border border-dashed bg-slate-50 p-3 text-xs text-slate-500">{String(section.emptyMessage)}</p>}</section>; })}</div>;
}

function formatPreviewValue(value: unknown) { return value == null || value === "" ? "Data pending" : Array.isArray(value) ? value.length : typeof value === "object" ? String(record(value).value ?? record(value).status ?? "Available") : String(value); }
function previewItem(item: unknown) { if (!item || typeof item !== "object") return String(item); const row = record(item); const title = String(row.title || row.keyword || row.name || row.recommendation || row.issueSummary || "Recorded item"); const detail = row.location ? ` · ${String(row.location)}` : row.status ? ` · ${String(row.status).replace(/_/g, " ")}` : ""; return `${title}${detail}`; }

function PreviewSection({ title, value }: { title: string; value: unknown }) { if (!value) return null; return <section><h3 className="text-lg font-bold text-slate-950">{title}</h3><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-700">{String(value)}</p></section>; }
function PreviewList({ title, value }: { title: string; value: unknown }) { const items = Array.isArray(value) ? value : []; if (!items.length) return null; return <section><h3 className="text-lg font-bold text-slate-950">{title}</h3><ul className="mt-2 list-disc space-y-1 pl-5 text-sm leading-6 text-slate-700">{items.map((item, index) => <li key={index}>{typeof item === "object" ? String(record(item).title || record(item).recommendation || JSON.stringify(item)) : String(item)}</li>)}</ul></section>; }
